-- HerpWatch — COMPLETE SETUP (schema + catalogue). GENERATED by scripts/build-seed.mjs.
-- Paste into Supabase → SQL Editor → Run. Safe to run again.

-- ═══════════════════════════════════════════════════════════════════════════
-- HerpWatch — Supabase schema. Idempotent: safe to re-run in the SQL Editor.
-- Then run supabase/seed.sql (generated by `node scripts/build-seed.mjs`).
--
-- Access model
--   • Anyone (even signed out) sees the species INDEX: names, family, IUCN,
--     venomous / poisonous flags (safety info is never paywalled).
--   • The full field-guide entry (photos, habitat, distribution notes, ID
--     notes, identify-wizard traits) needs an ENTITLEMENT for that species'
--     pack in a region where the species occurs (state pack) or for the whole
--     country (country pack). Enforced by RLS on public.species.
--   • Recording sightings / road-kill is free for every signed-in user.
--   • Entitlements are written ONLY by the razorpay-webhook Edge Function
--     (service role) or by admins via grant_pack(). Clients can only read.
--   • Public website gets aggregate stats + coarsened points via SECURITY
--     DEFINER functions — never raw rows or exact locations.
--
-- After the first sign-up, make yourself admin:
--   update public.profiles set role = 'admin' where username = '<you>';
-- ═══════════════════════════════════════════════════════════════════════════

create extension if not exists pgcrypto;

-- ─── reference tables ──────────────────────────────────────────────────────
create table if not exists public.packs (
  id    text primary key,                 -- snakes | lizards | frogs | turtles
  name  text not null,
  emoji text default '',
  color text default '#2f7d4f',
  blurb text default '',
  sort  int  default 0
);

create table if not exists public.regions (
  code   text primary key,                -- ISO 3166-1 / 3166-2: IN, IN-KL, LK …
  name   text not null,
  parent text references public.regions(code)
);

create table if not exists public.pack_prices (
  id          uuid primary key default gen_random_uuid(),
  pack_id     text not null references public.packs(id) on delete cascade,
  region_code text not null,              -- a region code, or '*state' = default for any single state
  paise       int  not null check (paise >= 0),
  days        int  not null default 365,
  active      boolean not null default true,
  unique (pack_id, region_code)
);

-- ─── profiles ──────────────────────────────────────────────────────────────
create table if not exists public.profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  username    text unique,
  email       text default '',
  full_name   text default '',
  phone       text default '',
  home_region text references public.regions(code),
  role        text not null default 'user'     check (role in ('user','reviewer','admin')),
  status      text not null default 'approved' check (status in ('approved','pending','blocked')),
  created_at  timestamptz default now()
);

alter table public.profiles add column if not exists email text default '';

create or replace function public.is_admin() returns boolean
language sql security definer stable set search_path = public as $$
  select exists(select 1 from public.profiles where id = auth.uid() and role = 'admin');
$$;
create or replace function public.is_reviewer() returns boolean
language sql security definer stable set search_path = public as $$
  select exists(select 1 from public.profiles where id = auth.uid() and role in ('admin','reviewer'));
$$;
create or replace function public.is_active() returns boolean
language sql security definer stable set search_path = public as $$
  select exists(select 1 from public.profiles where id = auth.uid() and status = 'approved');
$$;

-- profile creation on sign-up, self-repair and backfill live in supabase/accounts-live.sql

-- users may edit their own name/phone/region but never role/status
create or replace function public.guard_profile() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- auth.uid() is null in the SQL editor / service role: trusted, allowed
  if auth.uid() is not null and not public.is_admin() and (new.role is distinct from old.role or new.status is distinct from old.status) then
    raise exception 'only admins change role or status';
  end if;
  return new;
end $$;
drop trigger if exists guard_profile on public.profiles;
create trigger guard_profile before update on public.profiles for each row execute function public.guard_profile();

-- ─── species catalogue ─────────────────────────────────────────────────────
create table if not exists public.species (
  id              text primary key,             -- slug of scientific name
  pack_id         text not null references public.packs(id),
  common_name     text not null,
  scientific_name text not null,
  family          text default '',
  venom           text not null default 'non' check (venom in ('venomous','mild','non')),
  toxic           text not null default 'non' check (toxic in ('poisonous','non')),
  iucn            text not null default 'NE'  check (iucn in ('EX','EW','CR','EN','VU','NT','LC','DD','NE')),
  endemic         boolean default false,
  sensitive       boolean default false,        -- blur public locations to ~10 km
  size            text default '',
  habitat         text default '',
  distribution    text default '',
  id_notes        text default '',
  behaviour       text default '',
  similar_species text default '',
  images          jsonb default '[]'::jsonb,    -- [{url, credit, license}] or ["url", …]
  traits          jsonb default '{}'::jsonb,    -- identify wizard: {color:[], pattern, time}
  published       boolean default true,
  updated_at      timestamptz default now()
);
create index if not exists species_pack_idx on public.species(pack_id);

-- regional checklist = admin-curated "which species occur where" (also drives distribution & paywall)
create table if not exists public.checklist (
  region_code text references public.regions(code) on delete cascade,
  species_id  text references public.species(id)   on delete cascade,
  status      text default 'native' check (status in ('native','endemic','introduced','vagrant','uncertain')),
  primary key (region_code, species_id)
);
create index if not exists checklist_species_idx on public.checklist(species_id);

-- ─── entitlements (bought packs) & orders ─────────────────────────────────
create table if not exists public.orders (
  id           text primary key,              -- Razorpay order id
  user_id      uuid not null references auth.users(id) on delete cascade,
  items        jsonb not null,                -- [{pack, region, paise, days}] priced by the server
  amount_paise int not null,
  status       text not null default 'created' check (status in ('created','paid','refunded','failed')),
  payment_ref  text default '',
  created_at   timestamptz default now()
);

create table if not exists public.entitlements (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade,
  pack_id      text not null references public.packs(id),
  region_code  text not null references public.regions(code),
  valid_from   timestamptz not null default now(),
  valid_until  timestamptz,                   -- null = lifetime
  source       text not null default 'manual' check (source in ('manual','razorpay','play','apple','promo')),
  order_id     text references public.orders(id),
  payment_ref  text default '',
  granted_by   text default '',
  created_at   timestamptz default now()
);
create index if not exists entitlements_user_idx on public.entitlements(user_id);

create or replace function public.can_view_species(p_species text) returns boolean
language sql security definer stable set search_path = public as $$
  select public.is_admin() or exists (
    select 1 from public.species s
    join public.entitlements e on e.pack_id = s.pack_id
    join public.checklist c    on c.species_id = s.id and c.region_code = e.region_code
    where s.id = p_species and e.user_id = auth.uid()
      and e.valid_from <= now() and (e.valid_until is null or e.valid_until > now()));
$$;

-- ─── field records ─────────────────────────────────────────────────────────
-- eBird-style checklist ("trip"): a timed visit with protocol, effort and GPS track
create table if not exists public.trips (
  id           uuid primary key,              -- generated on the device (offline-safe upsert)
  user_id      uuid not null references auth.users(id) on delete cascade,
  region_code  text references public.regions(code),
  protocol     text not null default 'incidental' check (protocol in ('incidental','stationary','traveling','area','night_walk')),
  started_at   timestamptz not null,
  ended_at     timestamptz,
  duration_min int,
  distance_km  numeric(8,2),
  observers    int default 1,
  complete     boolean default false,         -- "reporting all species detected"
  track        jsonb default '[]'::jsonb,     -- [[lat,lng],…]
  lat          double precision,
  lng          double precision,
  notes        text default '',
  created_at   timestamptz default now()
);

create table if not exists public.sightings (
  id            uuid primary key,
  trip_id       uuid references public.trips(id) on delete cascade,
  user_id       uuid not null references auth.users(id) on delete cascade,
  species_id    text references public.species(id) on delete set null,
  species_text  text default '',              -- free text when unidentified / not in list
  count         int not null default 1 check (count >= 0),
  lat           double precision,
  lng           double precision,
  accuracy_m    real,
  observed_at   timestamptz not null default now(),
  region_code   text references public.regions(code),
  life_stage    text default '',              -- adult | juvenile | egg | tadpole | …
  sex           text default '',
  notes         text default '',
  photos        jsonb default '[]'::jsonb,
  review_status text not null default 'pending' check (review_status in ('pending','accepted','rejected')),
  created_at    timestamptz default now()
);
create index if not exists sightings_species_idx on public.sightings(species_id);
create index if not exists sightings_user_idx    on public.sightings(user_id);

-- road-kill logger: a driven/walked transect with its track, and carcass points on it
create table if not exists public.roadkill_surveys (
  id           uuid primary key,
  user_id      uuid not null references auth.users(id) on delete cascade,
  region_code  text references public.regions(code),
  mode         text default 'car' check (mode in ('walk','bicycle','motorbike','car','other')),
  road_name    text default '',
  road_type    text default '',
  started_at   timestamptz not null,
  ended_at     timestamptz,
  distance_km  numeric(8,2),
  track        jsonb default '[]'::jsonb,
  notes        text default '',
  created_at   timestamptz default now()
);
create table if not exists public.roadkill_records (
  id           uuid primary key,
  survey_id    uuid references public.roadkill_surveys(id) on delete cascade,
  user_id      uuid not null references auth.users(id) on delete cascade,
  species_id   text references public.species(id) on delete set null,
  species_text text default '',
  pack         text references public.packs(id),  -- group even when species unknown
  count        int not null default 1,
  lat          double precision,
  lng          double precision,
  accuracy_m   real,
  observed_at  timestamptz not null default now(),
  region_code  text references public.regions(code),
  condition    text default '',                    -- fresh | flattened | decomposed | dried
  side         text default '',                    -- left | right | centre | verge
  notes        text default '',
  photos       jsonb default '[]'::jsonb,
  created_at   timestamptz default now()
);

-- ─── row level security ────────────────────────────────────────────────────
alter table public.packs            enable row level security;
alter table public.regions          enable row level security;
alter table public.pack_prices      enable row level security;
alter table public.profiles         enable row level security;
alter table public.species          enable row level security;
alter table public.checklist        enable row level security;
alter table public.orders           enable row level security;
alter table public.entitlements     enable row level security;
alter table public.trips            enable row level security;
alter table public.sightings        enable row level security;
alter table public.roadkill_surveys enable row level security;
alter table public.roadkill_records enable row level security;

do $$
declare t text;
begin
  -- public reference data: everyone reads, admins write
  foreach t in array array['packs','regions','pack_prices','checklist'] loop
    execute format('drop policy if exists "read all" on public.%I', t);
    execute format('create policy "read all" on public.%I for select using (true)', t);
    execute format('drop policy if exists "admin write" on public.%I', t);
    execute format('create policy "admin write" on public.%I for all using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
  -- field records: owners manage their own; reviewers/admins see & moderate all
  foreach t in array array['trips','sightings','roadkill_surveys','roadkill_records'] loop
    execute format('drop policy if exists "own rows" on public.%I', t);
    execute format('create policy "own rows" on public.%I for all using (user_id = auth.uid()) with check (user_id = auth.uid() and public.is_active())', t);
    execute format('drop policy if exists "staff rows" on public.%I', t);
    execute format('create policy "staff rows" on public.%I for all using (public.is_reviewer()) with check (public.is_reviewer())', t);
  end loop;
end $$;

-- owners may not self-accept their own sightings
create or replace function public.guard_review() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_reviewer() then
    new.review_status := case when tg_op = 'INSERT' then 'pending' else old.review_status end;
  end if;
  return new;
end $$;
drop trigger if exists guard_review on public.sightings;
create trigger guard_review before insert or update on public.sightings for each row execute function public.guard_review();

drop policy if exists "profiles: own"   on public.profiles;
drop policy if exists "profiles: admin" on public.profiles;
drop policy if exists "profiles: own update" on public.profiles;
create policy "profiles: own"   on public.profiles for select using (id = auth.uid());
create policy "profiles: own update" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "profiles: admin" on public.profiles for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists "species: entitled" on public.species;
drop policy if exists "species: admin"    on public.species;
create policy "species: entitled" on public.species for select using (published and public.can_view_species(id));
create policy "species: admin"    on public.species for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists "entitlements: own"   on public.entitlements;
drop policy if exists "entitlements: admin" on public.entitlements;
create policy "entitlements: own"   on public.entitlements for select using (user_id = auth.uid());
create policy "entitlements: admin" on public.entitlements for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists "orders: own"   on public.orders;
drop policy if exists "orders: admin" on public.orders;
create policy "orders: own"   on public.orders for select using (user_id = auth.uid());
create policy "orders: admin" on public.orders for select using (public.is_admin());

-- ─── views ─────────────────────────────────────────────────────────────────
-- free index (owner-rights view → bypasses species RLS, exposes only basic columns)
drop view if exists public.species_index;
create view public.species_index as
  select s.id, s.pack_id, s.common_name, s.scientific_name, s.family, s.venom, s.toxic, s.iucn,
         s.endemic, s.sensitive,
         coalesce((select array_agg(c.region_code) from public.checklist c where c.species_id = s.id), '{}') as regions
  from public.species s where s.published;
grant select on public.species_index to anon, authenticated;

-- full entry, respects species RLS (security_invoker) → empty unless entitled
drop view if exists public.species_full;
create view public.species_full with (security_invoker = true) as
  select s.*, coalesce((select array_agg(c.region_code) from public.checklist c where c.species_id = s.id), '{}') as regions
  from public.species s;
grant select on public.species_full to authenticated;

-- ─── admin RPCs ────────────────────────────────────────────────────────────
create or replace function public.grant_pack(p_user uuid, p_pack text, p_region text, p_days int default 365)
returns public.entitlements language plpgsql security definer set search_path = public as $$
declare r public.entitlements;
begin
  if not public.is_admin() then raise exception 'admins only'; end if;
  values (p_user, p_pack, p_region,
          case when p_days is null then null else now() + make_interval(days => p_days) end,
          'manual', coalesce((select username from public.profiles where id = auth.uid()), ''))
  returning * into r;
  return r;
end $$;

create or replace function public.set_checklist(p_region text, p_species text[])
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not public.is_admin() then raise exception 'admins only'; end if;
  delete from public.checklist where region_code = p_region and not (species_id = any(p_species));
    select p_region, unnest(p_species) on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- ─── public reporting RPCs (website) ───────────────────────────────────────
create or replace function public.public_stats() returns jsonb
language sql security definer stable set search_path = public as $$
with s as (select x.*, sp.pack_id, sp.iucn, sp.venom from public.sightings x left join public.species sp on sp.id = x.species_id where x.review_status <> 'rejected'),
     r as (select x.*, coalesce(sp.pack_id, x.pack) pk from public.roadkill_records x left join public.species sp on sp.id = x.species_id),
     km as (select coalesce(sum(distance_km),0) v, count(*) n from public.roadkill_surveys)
select jsonb_build_object(
  'totals', jsonb_build_object(
     'sightings', (select coalesce(sum(count),0) from s),
     'records', (select count(*) from s),
     'species', (select count(distinct species_id) from s),
     'observers', (select count(distinct user_id) from (select user_id from s union select user_id from r) u),
     'roadkill', (select coalesce(sum(count),0) from r),
     'roadkill_surveys', (select n from km),
     'roadkill_km', (select round(v,1) from km),
     'roadkill_per_100km', (select case when v > 0 then round((select coalesce(sum(count),0) from r) / v * 100, 1) else 0 end from km)),
  'by_pack',  coalesce((select jsonb_agg(jsonb_build_object('pack', pack_id, 'n', n) order by n desc) from (select pack_id, sum(count) n from s group by 1) q), '[]'),
  'roadkill_by_pack', coalesce((select jsonb_agg(jsonb_build_object('pack', pk, 'n', n) order by n desc) from (select pk, sum(count) n from r group by 1) q), '[]'),
  'by_iucn',  coalesce((select jsonb_agg(jsonb_build_object('iucn', iucn, 'n', n) order by n desc) from (select iucn, sum(count) n from s where iucn is not null group by 1) q), '[]'),
  'by_venom', coalesce((select jsonb_agg(jsonb_build_object('venom', venom, 'n', n) order by n desc) from (select venom, sum(count) n from s where pack_id = 'snakes' group by 1) q), '[]'),
  'by_region',coalesce((select jsonb_agg(jsonb_build_object('region', region_code, 'n', n) order by n desc) from (select region_code, sum(count) n from s where region_code is not null group by 1) q), '[]'),
  'by_month', coalesce((select jsonb_agg(jsonb_build_object('month', m, 'sightings', a, 'roadkill', b) order by m) from (
       select m, sum(a) a, sum(b) b from (
         select to_char(observed_at,'YYYY-MM') m, count a, 0 b from s
         union all select to_char(observed_at,'YYYY-MM'), 0, count from r) z group by m) q), '[]'),
  'top_species', coalesce((select jsonb_agg(jsonb_build_object('species_id', q.species_id, 'n', q.n, 'common', sp.common_name, 'sci', sp.scientific_name) order by q.n desc)
       from (select species_id, sum(count) n from s where species_id is not null group by 1 order by 2 desc limit 12) q join public.species sp on sp.id = q.species_id), '[]'),
  'roadkill_species', coalesce((select jsonb_agg(jsonb_build_object('species_id', q.species_id, 'n', q.n, 'common', sp.common_name, 'sci', sp.scientific_name) order by q.n desc)
       from (select species_id, sum(count) n from r where species_id is not null group by 1 order by 2 desc limit 12) q join public.species sp on sp.id = q.species_id), '[]')
);
$$;

-- coarsened points: 0.01° (~1 km) normally, 0.1° (~10 km) for sensitive species
create or replace function public.public_points() returns table(kind text, species_id text, pack text, iucn text, lat double precision, lng double precision, month text)
language sql security definer stable set search_path = public as $$
  select 'sighting', x.species_id, sp.pack_id, sp.iucn,
         round(x.lat::numeric, case when sp.sensitive then 1 else 2 end)::float8,
         round(x.lng::numeric, case when sp.sensitive then 1 else 2 end)::float8,
         to_char(x.observed_at,'YYYY-MM')
  from public.sightings x left join public.species sp on sp.id = x.species_id
  where x.review_status <> 'rejected' and x.lat is not null
  union all
  select 'roadkill', x.species_id, coalesce(sp.pack_id, x.pack), sp.iucn,
         round(x.lat::numeric, case when sp.sensitive then 1 else 2 end)::float8,
         round(x.lng::numeric, case when sp.sensitive then 1 else 2 end)::float8,
         to_char(x.observed_at,'YYYY-MM')
  from public.roadkill_records x left join public.species sp on sp.id = x.species_id
  where x.lat is not null;
$$;

create or replace function public.public_tracks() returns table(id uuid, road_name text, distance_km numeric, track jsonb)
language sql security definer stable set search_path = public as $$
  select id, road_name, distance_km,
    coalesce((select jsonb_agg(jsonb_build_array(round((p->>0)::numeric,2), round((p->>1)::numeric,2))) from jsonb_array_elements(track) p), '[]')
  from public.roadkill_surveys;
$$;

grant execute on function public.public_stats()  to anon, authenticated;
grant execute on function public.public_points() to anon, authenticated;
grant execute on function public.public_tracks() to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- v2 · production hardening (idempotent: upgrades an existing database in place)
--   • updated_at everywhere · review metadata (who/when/why)
--   • data validation (coordinates, counts, dates, distances)
--   • records can only be attached to the owner's own checklist / survey
--   • audit log of every admin change to checklists, species, prices, roles, packs
--   • indexes for the dashboard's filters
-- ═══════════════════════════════════════════════════════════════════════════

-- updated_at ----------------------------------------------------------------
create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$ begin new.updated_at := now(); return new; end $$;
do $$
declare t text;
begin
  foreach t in array array['profiles','species','checklist','pack_prices','trips','sightings','roadkill_surveys','roadkill_records','entitlements'] loop
    execute format('alter table public.%I add column if not exists updated_at timestamptz not null default now()', t);
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()', t);
  end loop;
end $$;

-- review metadata -------------------------------------------------------------
alter table public.sightings add column if not exists reviewed_by uuid references auth.users(id) on delete set null;
alter table public.sightings add column if not exists reviewed_at timestamptz;
alter table public.sightings add column if not exists review_note text not null default '';

create or replace function public.guard_review() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_reviewer() then
    -- observers can never accept their own records; editing a record sends it back to review
    new.review_status := 'pending';
    if tg_op = 'UPDATE' then new.reviewed_by := old.reviewed_by; new.reviewed_at := old.reviewed_at; new.review_note := old.review_note; end if;
  elsif tg_op = 'INSERT' or new.review_status is distinct from old.review_status then
    new.reviewed_by := case when new.review_status = 'pending' then null else auth.uid() end;
    new.reviewed_at := case when new.review_status = 'pending' then null else now() end;
  end if;
  return new;
end $$;
drop trigger if exists guard_review on public.sightings;
create trigger guard_review before insert or update on public.sightings for each row execute function public.guard_review();

-- validation (NOT VALID: enforced for new/edited rows, existing rows untouched) --
do $$
declare c record;
begin
  for c in select * from (values
    ('sightings', 'sightings_lat_ok', 'lat is null or lat between -90 and 90'),
    ('sightings', 'sightings_lng_ok', 'lng is null or lng between -180 and 180'),
    ('sightings', 'sightings_when_ok', $c$observed_at <= now() + interval '2 days'$c$),
    ('sightings', 'sightings_has_taxon', 'species_id is not null or length(trim(species_text)) > 0'),
    ('trips', 'trips_lat_ok', 'lat is null or lat between -90 and 90'),
    ('trips', 'trips_lng_ok', 'lng is null or lng between -180 and 180'),
    ('trips', 'trips_effort_ok', 'coalesce(duration_min, 0) >= 0 and coalesce(distance_km, 0) >= 0 and coalesce(observers, 1) >= 1'),
    ('trips', 'trips_times_ok', 'ended_at is null or ended_at >= started_at'),
    ('roadkill_surveys', 'rk_surveys_ok', 'coalesce(distance_km, 0) >= 0 and (ended_at is null or ended_at >= started_at)'),
    ('roadkill_records', 'rk_records_lat_ok', 'lat is null or lat between -90 and 90'),
    ('roadkill_records', 'rk_records_lng_ok', 'lng is null or lng between -180 and 180'),
    ('roadkill_records', 'rk_records_count_ok', 'count >= 1'),
    ('profiles', 'profiles_username_ok', $c$username ~ '^[a-z0-9_.-]{3,40}$'$c$)
  ) v(tbl, name, expr) loop
    if not exists (select 1 from pg_constraint where conname = c.name) then
      execute format('alter table public.%I add constraint %I check (%s) not valid', c.tbl, c.name, c.expr);
    end if;
  end loop;
end $$;

-- a record must belong to the same person as its checklist / survey -----------
create or replace function public.guard_parent_owner() returns trigger
language plpgsql security definer set search_path = public as $$
declare owner uuid; rec jsonb := to_jsonb(new);   -- jsonb: one function serves both tables
begin
  if tg_table_name = 'sightings' and rec->>'trip_id' is not null then
    select user_id into owner from public.trips where id = (rec->>'trip_id')::uuid;
  elsif tg_table_name = 'roadkill_records' and rec->>'survey_id' is not null then
    select user_id into owner from public.roadkill_surveys where id = (rec->>'survey_id')::uuid;
  end if;
  if owner is not null and owner <> new.user_id then
    raise exception 'record must belong to the owner of its checklist/survey' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists guard_parent_owner on public.sightings;
create trigger guard_parent_owner before insert or update on public.sightings for each row execute function public.guard_parent_owner();
drop trigger if exists guard_parent_owner on public.roadkill_records;
create trigger guard_parent_owner before insert or update on public.roadkill_records for each row execute function public.guard_parent_owner();

-- audit log of admin changes ---------------------------------------------------
create table if not exists public.audit_log (
  id         bigserial primary key,
  at         timestamptz not null default now(),
  actor      uuid,                       -- auth.uid(); null = SQL editor / server
  actor_name text default '',
  tbl        text not null,
  action     text not null,              -- INSERT | UPDATE | DELETE
  row_key    text default '',
  old_row    jsonb,
  new_row    jsonb
);
create index if not exists audit_log_at_idx on public.audit_log(at desc);
alter table public.audit_log enable row level security;
drop policy if exists "audit: admin read" on public.audit_log;
create policy "audit: admin read" on public.audit_log for select using (public.is_admin());

create or replace function public.audit_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare o jsonb := case when tg_op <> 'INSERT' then to_jsonb(old) end;
        n jsonb := case when tg_op <> 'DELETE' then to_jsonb(new) end;
        k text;
begin
  -- profiles: only role / status changes are interesting
  if tg_table_name = 'profiles' and (tg_op <> 'UPDATE'
     or (o->>'role' is not distinct from n->>'role' and o->>'status' is not distinct from n->>'status')) then
    return null;
  end if;
  -- the initial catalogue load (SQL editor / setup, no signed-in user) is not audited
  if auth.uid() is null and tg_op = 'INSERT' and tg_table_name in ('checklist', 'species', 'pack_prices') then
    return null;
  end if;
  k := coalesce(n, o)->>'id';
  if tg_table_name = 'checklist' then k := (coalesce(n, o)->>'region_code') || ':' || (coalesce(n, o)->>'species_id'); end if;
  values (auth.uid(), coalesce((select username from public.profiles where id = auth.uid()), ''), tg_table_name, tg_op, coalesce(k, ''), o, n);
  return null;
end $$;
do $$
declare t text;
begin
  foreach t in array array['checklist','species','pack_prices','entitlements','profiles'] loop
    execute format('drop trigger if exists audit_change on public.%I', t);
    execute format('create trigger audit_change after insert or update or delete on public.%I for each row execute function public.audit_change()', t);
  end loop;
end $$;

